describe('Container', () => {
  it('should render its children correctly', () => {
    const testChildText = 'This is a test child';
    render(<Container><div>{testChildText}</div></Container>);
    expect(screen.getByText(testChildText)).toBeInTheDocument();
  });

  it('should render multiple children correctly', () => {
    const testChild1 = 'First child';
    const testChild2 = 'Second child';
    render(
      <Container>
        <span>{testChild1}</span>
        <p>{testChild2}</p>
      </Container>
    );
    expect(screen.getByText(testChild1)).toBeInTheDocument();
    expect(screen.getByText(testChild2)).toBeInTheDocument();
  });

  it('should render an empty container if no children are provided', () => {
    const { container } = render(<Container />);
    // Expect the root div of the styled component to be present, but no children.
    // The styled component will render a div even if children are empty.
    expect(container.firstChild).toBeInTheDocument();
    expect(container.firstChild.tagName).toBe('DIV');
    expect(container.firstChild.children.length).toBe(0);
  });

  it('should render a div as its root element', () => {
    render(<Container><span>Child</span></Container>);
    const containerElement = screen.getByText('Child').parentElement;
    expect(containerElement).toBeInTheDocument();
    expect(containerElement.tagName).toBe('DIV');
  });
});

